#include "mgt/batch_norm_training.hpp"
#include <algorithm>
#include <limits>
namespace mgt {
Status BuildBatchNormTrainingPlan(std::uint32_t lh1,std::uint32_t lh2,std::uint32_t ph1,std::uint32_t ph2,std::uint32_t blocks,std::uint32_t rows,BatchNormTrainingPlan* out){if(!lh1||!lh2||ph1<lh1||ph2<lh2||blocks>64||!rows||!out)return Status::kInvalidConfig;const std::uint64_t logical=static_cast<std::uint64_t>(lh1)+static_cast<std::uint64_t>(1U+2U*blocks)*lh2;const std::uint64_t storage=static_cast<std::uint64_t>(ph1)+static_cast<std::uint64_t>(1U+2U*blocks)*ph2;if(storage>std::numeric_limits<std::uint64_t>::max()/rows)return Status::kCapacityExceeded;BatchNormTrainingPlan p{};p.logical_feature_count=logical;p.storage_feature_count=storage;p.trainable_count=2*logical;p.running_count=2*logical;p.normalized_count=storage*rows;p.mean_offset=p.normalized_count;p.inv_std_offset=p.mean_offset+logical;p.reduction_offset=p.inv_std_offset+logical;p.reduction_count=2ULL*std::max(lh1,lh2);p.workspace_floats=p.reduction_offset+p.reduction_count;std::uint64_t affine=0,norm=0,stats=0;auto add=[&](std::uint32_t l,std::uint32_t stride){p.sites.push_back({l,stride,affine,affine,norm,p.mean_offset+stats,p.inv_std_offset+stats});affine+=l;norm+=static_cast<std::uint64_t>(rows)*stride;stats+=l;};add(lh1,ph1);add(lh2,ph2);for(std::uint32_t b=0;b<blocks;b++){add(lh2,ph2);add(lh2,ph2);}if(affine!=logical||norm!=p.normalized_count||stats!=logical)return Status::kInvalidConfig;*out=std::move(p);return Status::kOk;}
BatchNormTrainingState InitializeBatchNormTrainingState(const BatchNormTrainingPlan& p){BatchNormTrainingState s;if(!p.logical_feature_count||p.trainable_count!=2*p.logical_feature_count||p.running_count!=2*p.logical_feature_count)return s;s.affine.assign(p.trainable_count,0.0f);s.running.assign(p.running_count,0.0f);s.adam_m.assign(p.trainable_count,0.0f);s.adam_v.assign(p.trainable_count,0.0f);std::fill(s.affine.begin(),s.affine.begin()+p.logical_feature_count,1.0f);std::fill(s.running.begin()+p.logical_feature_count,s.running.end(),1.0f);return s;}
}